<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{NButton,NDataTable,NForm,NFormItem,NInput,NModal,NSelect,useMessage}from'naive-ui';import{api}from'../api';const message=useMessage(),rows=ref<any[]>([]),show=ref(false),form=reactive<any>({title:'',slug:'',content:'',status:0,seo_description:''});async function load(){const x:any=await api.get('/pages');rows.value=x.list}function edit(r?:any){Object.assign(form,r||{id:0,title:'',slug:'',content:'',status:0,seo_description:''});show.value=true}async function save(){try{form.id?await api.put(`/pages/${form.id}`,form):await api.post('/pages',form);show.value=false;load()}catch(e:any){message.error(e.message)}}const columns=[{title:'标题',key:'title'},{title:'Slug',key:'slug'},{title:'状态',key:'status',render:(r:any)=>r.status===1?'已发布':'草稿'},{title:'操作',key:'x',render:(r:any)=>(window as any).Vue?.h?.(NButton,{onClick:()=>edit(r)},()=> '编辑')||r.title}];onMounted(load)</script>
<template><div class="page-head"><h1>单页管理</h1><n-button type="primary" @click="edit()">新建单页</n-button></div><div class="panel"><div v-for="r in rows" :key="r.id" class="release" style="display:flex;justify-content:space-between"><div><b>{{r.title}}</b><div style="color:#8b93a1">/pages/{{r.slug}} · {{r.status===1?'已发布':'草稿'}}</div></div><n-button @click="edit(r)">编辑</n-button></div></div><n-modal v-model:show="show" preset="card" title="编辑单页" style="max-width:720px"><n-form label-placement="top"><div class="form-grid"><n-form-item label="标题"><n-input v-model:value="form.title"/></n-form-item><n-form-item label="Slug"><n-input v-model:value="form.slug"/></n-form-item><n-form-item label="状态"><n-select v-model:value="form.status" :options="[{label:'草稿',value:0},{label:'发布',value:1}]"/></n-form-item><n-form-item class="wide" label="内容（Markdown）"><n-input v-model:value="form.content" type="textarea" :rows="12"/></n-form-item></div><n-button type="primary" @click="save">保存</n-button></n-form></n-modal></template>

